// Логирование приложения.
//
// Формат — одна JSON-строка на запись (см. write_line в log.cpp):
//   {"ts":"2026-08-29T12:34:56.789Z","level":"info","service":"wallet-api",
//    "trace_id":"1a2b...","msg":"..."}
// level — ровно одно из четырёх значений: "error", "warn", "info", "debug"
// (см. функции ниже) — само сообщение об ошибке/событии всегда в "msg", не
// размазано по другим полям (details добавляет СВОИ поля рядом — duration_ms,
// sql и т.п., — но не подменяет msg/level, см. write_line в log.cpp).
// trace_id есть только пока он выставлен (см. set_trace_id ниже) — иначе
// поле просто отсутствует (например, у строк "listening on ..." до первого
// запроса). Структурированный формат — чтобы логи парсились/фильтровались
// по полю (jq, Loki, ELK...), а не грепались как текст; ts — всегда UTC,
// независимо от таймзоны хоста, чтобы строки из разных сервисов/машин
// сравнивались без пересчёта.
//
// По умолчанию: Windows — папка logs/ с файлом на каждый день (см. init()),
// Linux/Docker — stdout/stderr, как и положено для контейнеров (раннтайм
// сам собирает логи с потоков вывода процесса; писать в файл внутри
// контейнера — анти-паттерн: логи пропадают вместе с контейнером, если не
// подключён volume). Это решение принимает вызывающий код (main.cpp) через
// LOG_DIR — см. README.md.
#pragma once

#include <string>

#include "nlohmann/json.hpp"

namespace applog {

// dir пустой -> вывод в stdout/stderr; иначе -> запись в
// "<dir>/<YYYY-MM-DD>-<service_name>.log" (папка создаётся сама; дата в
// имени файла — ЛОКАЛЬНАЯ, это для удобства человека на Windows-хосте, на
// содержимое строк не влияет, см. ts выше). service_name — короткое имя
// сервиса (например, "google-auth", "wallet-api", "wallet-gateway") —
// попадает и в имя файла, и в поле "service" каждой JSON-строки. Ротация —
// по смене календарной даты: как только день сменился, следующая запись
// уходит уже в новый файл, старые не трогаются и не удаляются (внешняя
// система вроде logrotate/сжатия бэкапов — не забота этого модуля).
// Вызывать один раз при старте, до первого info()/error().
void init(const std::string& dir, const std::string& service_name);

// Новый случайный trace-id (32 hex-символа, без разделителей — совместимо по
// виду с trace-id из W3C Trace Context на случай, если сервисы позже
// перейдут на полноценный трейсинг вроде OpenTelemetry). Вызывает ТОЛЬКО
// wallet-gateway — единственная точка входа для браузера (см. его main.cpp)
// — когда запрос пришёл без своего X-Trace-Id; остальные сервисы только
// читают уже готовый id из заголовка и никогда не порождают новый на
// середине пути, иначе один запрос браузера склеился бы в логах как
// несколько разных трейсов.
std::string new_trace_id();

// trace_id для ТЕКУЩЕГО потока — httplib обрабатывает каждый запрос от
// pre_routing_handler до set_logger на одном потоке целиком, но затем
// отдаёт этот поток в пул для следующего, никак не связанного запроса —
// поэтому это состояние thread_local, а не глобальная переменная, и
// set_trace_id/clear_trace_id нужно вызывать парой на каждый запрос (см.
// main.cpp каждого сервиса), иначе id рано или поздно попадёт в лог чужого
// запроса, который этот же поток обслужит следующим.
void set_trace_id(const std::string& trace_id);
void clear_trace_id();

// Текущий trace_id этого потока (пустая строка, если не выставлен) — чтобы
// исходящие HTTP-вызовы внутри обработки запроса (проксирование в
// wallet-gateway, обновление JWKS) могли передать его дальше тем же
// заголовком X-Trace-Id, не протаскивая id отдельным параметром через всю
// цепочку вызовов.
std::string current_trace_id();

// Четыре уровня — error/warn/info/debug (в этом же порядке по убыванию
// серьёзности), больше никаких строк в поле "level" не бывает (см. write_line
// в log.cpp — уровень передаётся туда буквальным литералом из этих функций,
// не значением снаружи). error — только на то, что реально мешает ответить
// клиенту осмысленно (см. db_query_failed в db.cpp); warn — заметили
// странность, но обработали и продолжили; debug — подробности не для
// постоянного мониторинга, полезны только при локальной отладке.
//
// Минимальный уровень — переменная окружения LOG_LEVEL (error/warn/info/
// debug), читается один раз при первой записи; строки ниже неё не пишутся
// вовсе. Не задана или не распознана — debug, то есть пишется всё, как было
// до появления LOG_LEVEL.
void error(const std::string& message);
void warn(const std::string& message);
void info(const std::string& message);
void debug(const std::string& message);

// То же самое, плюс произвольные структурированные поля поверх строки лога
// (details ДОЛЖЕН быть JSON-объектом — иначе молча игнорируется, см.
// write_line в log.cpp). Основной потребитель — db::Database::exec (см.
// db.cpp): duration_ms/rows/sql, чтобы латенси SQL-запросов агрегировалась
// по полю (jq/Loki), а не парсилась из текста msg. Системные поля
// (ts/level/service/trace_id/msg) всегда ставятся ПОСЛЕ details и
// перетирают одноимённые ключи в нём — details не может подделать их или
// внести путаницу в трейс.
void error(const std::string& message, const nlohmann::json& details);
void warn(const std::string& message, const nlohmann::json& details);
void info(const std::string& message, const nlohmann::json& details);
void debug(const std::string& message, const nlohmann::json& details);

// Отметка "начало обработки запроса" для ЭТОГО потока — вызывать в
// pre_routing_handler, как можно раньше (см. main.cpp каждого сервиса), тем
// же приёмом, что и set_trace_id (thread_local, парой на каждый запрос —
// httplib переиспользует поток из пула для следующего, не связанного
// запроса). request_duration_ms() — сколько прошло с этой отметки, кладётся
// как duration_ms в details строки set_logger — это время ВСЕГО запроса
// целиком (routing + хендлер + все SQL внутри), не путать с duration_ms у
// db::Database::exec (см. db.cpp) — тот мерит только один SQL-вызов.
void start_request_timer();
double request_duration_ms();

// Логическое имя ручки (например "DELETE /api/wallets/:id") — ТОТ ЖЕ
// литерал, что и паттерн регистрации маршрута (svr.Delete("/api/wallets/:id",
// ...)), не реальный путь запроса (req.path содержит конкретный id — по нему
// перцентили/среднее не сгруппировать, каждый вызов был бы своей группой).
// Выставляется явно в начале каждого хендлера (см. main.cpp/wallet.cpp/
// google.cpp — по месту регистрации маршрута, копия той же строки). Тот же
// thread_local приём, что и set_trace_id — парой на каждый запрос.
void set_route(const std::string& route);
std::string current_route();

// sub из уже проверенного JWT — выставляется один раз, там, где токен
// впервые верифицируется в этом сервисе (session::current_user в wallet-api,
// auth::authenticate в google-auth, has_valid_token в wallet-gateway), и
// дальше сам попадает во все строки лога этого запроса — не нужно протаскивать
// user_id отдельным параметром через всю цепочку вызовов, как и с trace_id.
void set_user(const std::string& user_id);
std::string current_user_id();

// Очищает ВЕСЬ per-request thread-local контекст этого модуля разом
// (trace_id + route + user_id) — вызывать один раз, в самом конце обработки
// запроса (см. set_logger в каждом main.cpp), СРАЗУ ПОСЛЕ финальной строки
// лога (иначе именно она этот контекст и потеряет). Дальше поток уходит в
// пул httplib обслуживать следующий, никак не связанный запрос — оставлять
// что-либо из этого висеть до следующего вызова set_trace_id/set_route/
// set_user нельзя, иначе одна из строк лога чужого запроса случайно
// unаследует контекст этого.
void clear_request_context();

} // namespace applog
